from taf.sw.dcap.rd.schemas.base import SchemaField, SchemaObject


class GetSessionInfoV1(SchemaObject):
    session_name = SchemaField(name="session_name")
    user_name = SchemaField(name="user_name")

    def __init__(self, session_name=None, user_name=None):
        self.session_name = session_name
        self.user_name = user_name

        super(GetSessionInfoV1, self).__init__()
